INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5b92d0cf-d481-570b-9630-d138cea40b5d', 'South Africa Employment Equity Act 55 of', 'Employment Equity Act 55 of 1998', 'The Employment Equity Act 55 of 1998 intends: to provide for employment equity; and to provide for matters incidental thereto.', 'The Employment Equity Act 55 of 1998 intends: to provide for employment equity; and to provide for matters incidental thereto.', 'The Employment Equity Act 55 of 1998 intends: to provide for employment equity; and to provide for matters incidental thereto.', 'South Africa', 'social', 'in_force', '1998-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_7', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23e8a2c7-4e53-57e3-9195-0a2df7afc33c', 'South Africa Code of Corporate Practices & Conduct', 'The Code of Corporate Practices & Conduct, 1994', 'This is the 20th Chapter of the code of Corporate Practices and Conduct.', 'This is the 20th Chapter of the code of Corporate Practices and Conduct.', 'This is the 20th Chapter of the code of Corporate Practices and Conduct.', 'South Africa', 'governance', 'in_force', '1994-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_21', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7c62ed6a-ee96-504c-b137-f6bc3c5d7cd3', 'South Korea Mandatory Climate Disclosure (Exposure Draft)', 'Mandatory Climate Disclosure (Exposure Draft)', 'The Korea Sustainability Standards Board (KSSB) introduced the Korean Sustainability Disclosure Standards (KSDS) on May 2, 2024, with mandatory climate-related disclosures to begin in 2026. The standards aim to enhance transparency and align with global disclosure frameworks, particularly IFRS Sustainability Disclosure Standards and TCFD recommendations. The KSDS framework consists of three parts: KSSB 1 (general requirements), KSSB 2 (climate-related disclosures), and KSSB 101 (voluntary, country-specific disclosures).
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b8afc816-5cf4-5cb5-8285-f657a4ed8924', 'South Korea Bill on Human Rights and Environmental Protection', 'Bill on Human Rights and Environmental Protection for Sustainable Business Management 2023', 'The Bill on Human Rights and Environmental Protection for Sustainable Business Management 2023 in South Korea aims to promote sustainability and corporate responsibility by requiring companies to conduct human rights and environmental due diligence. The policy emphasizes preventing violations, supporting victims, and establishing an implementation system. It targets improving non-financial performance indicators, aligning with international trends, and ensuring transparency and accountability. The policy covers companies both domestically and internationally, with a focus on respecting human rights and the environment.', 'The Bill on Human Rights and Environmental Protection for Sustainable Business Management 2023 in South Korea aims to promote sustainability and corporate responsibility by requiring companies to conduct human rights and environmental due diligence. The policy emphasizes preventing violations, supporting victims, and establishing an implementation system. It targets improving non-financial performance indicators, aligning with international trends, and ensuring transparency and accountability. The policy covers companies both domestically and internationally, with a focus on respecting human rights and the environment.', 'The Bill on Human Rights and Environmental Protection for Sustainable Business Management 2023 in South Korea aims to promote sustainability and corporate responsibility by requiring companies to conduct human rights and environmental due diligence. The policy emphasizes preventing violations, supporting victims, and establishing an implementation system. It targets improving non-financial performance indicators, aligning with international trends, and ensuring transparency and accountability. The policy covers companies both domestically and internationally, with a focus on respecting human rights and the environment.', 'South Korea', 'climate', 'in_force', '2023-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_10', ARRAY['south korea', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('041db5c0-94c8-585d-89a0-a16ea445b9e7', 'South Korea Framework Act on Sustainable Development', 'Framework Act on Sustainable Development, 2022', 'The purpose of this Act is to ensure that present and future generations enjoy a better life, and to achieve the sustainable development of the State and local areas, and, by extension, human society by pursuing sustainable economic growth and an inclusive society, and also by seeking to tackle climate and environmental crisis through balance and harmony between the economy, society, and the environment.', 'The purpose of this Act is to ensure that present and future generations enjoy a better life, and to achieve the sustainable development of the State and local areas, and, by extension, human society by pursuing sustainable economic growth and an inclusive society, and also by seeking to tackle climate and environmental crisis through balance and harmony between the economy, society, and the environment.', 'The purpose of this Act is to ensure that present and future generations enjoy a better life, and to achieve the sustainable development of the State and local areas, and, by extension, human society by pursuing sustainable economic growth and an inclusive society, and also by seeking to tackle climate and environmental crisis through balance and harmony between the economy, society, and the environment.', 'South Korea', 'climate', 'in_force', '2022-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_14', ARRAY['sdg2', 'sdg13', 'regulations', 'sdg7', 'south korea', 'mandatory', 'sdg12', 'disclosure', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b945550a-0fe5-501f-83c3-d4e07a4d07ba', 'South Korea Business and Human Rights Reporting Directive', 'Business and Human Rights Reporting Directive', 'This guidance was drafted to present how institutions (companies) that have started to implement business and human rights management through the "Human Rights Management Manual for State Owned Enterprises" (2018) should review their implementation and report to relevant stakeholders.', 'This guidance was drafted to present how institutions (companies) that have started to implement business and human rights management through the "Human Rights Management Manual for State Owned Enterprises" (2018) should review their implementation and report to relevant stakeholders.', 'This guidance was drafted to present how institutions (companies) that have started to implement business and human rights management through the "Human Rights Management Manual for State Owned Enterprises" (2018) should review their implementation and report to relevant stakeholders.', 'South Korea', 'climate', 'in_force', '2022-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_18', ARRAY['regulations', 'south korea', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('451cd8c8-d52c-5924-9824-3c4767bd8786', 'South Korea Charter and Guidelines for Human Rights in', 'Charter and Guidelines for Human Rights in Sports 2022', 'The Charter and Guidelines for Human Rights in Sports 2022 by South Korea aim to ensure equal access to sports activities for all individuals regardless of gender, sexual orientation, disability, age, or other factors. The policy emphasizes the right to participate freely in sports, interact with others, access sports facilities, and pursue excellence without discrimination. It also highlights the importance of sports education and career opportunities without bias. The policy sets out to promote human rights in the field of sports and create a fair and inclusive sports environment.', 'The Charter and Guidelines for Human Rights in Sports 2022 by South Korea aim to ensure equal access to sports activities for all individuals regardless of gender, sexual orientation, disability, age, or other factors. The policy emphasizes the right to participate freely in sports, interact with others, access sports facilities, and pursue excellence without discrimination. It also highlights the importance of sports education and career opportunities without bias. The policy sets out to promote human rights in the field of sports and create a fair and inclusive sports environment.', 'The Charter and Guidelines for Human Rights in Sports 2022 by South Korea aim to ensure equal access to sports activities for all individuals regardless of gender, sexual orientation, disability, age, or other factors. The policy emphasizes the right to participate freely in sports, interact with others, access sports facilities, and pursue excellence without discrimination. It also highlights the importance of sports education and career opportunities without bias. The policy sets out to promote human rights in the field of sports and create a fair and inclusive sports environment.', 'South Korea', 'climate', 'in_force', '2022-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_19', ARRAY['sdg4', 'guidance_frameworks', 'other sustainability policy', 'sdg10', 'south korea', 'sdg5', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f128b815-0623-5d84-8955-bfab270d0bd9', 'South Korea K-Taxonomy Guidelines', 'K-Taxonomy Guidelines, 2022', 'The K-Taxonomy has been designed to establish and lay out clear principles and criteria for genuine green economic activities so that more green capital could be invested in green projects or green technologies.', 'The K-Taxonomy has been designed to establish and lay out clear principles and criteria for genuine green economic activities so that more green capital could be invested in green projects or green technologies.', 'The K-Taxonomy has been designed to establish and lay out clear principles and criteria for genuine green economic activities so that more green capital could be invested in green projects or green technologies.', 'South Korea', 'climate', 'in_force', '2022-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_9', ARRAY['sdg13', 'south korea', 'sdg6', 'voluntary', 'sdg12', 'disclosure', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('99584f1e-35e2-53ef-82f5-8378e76550ed', 'South Korea Environmental Technology and Industry Support Act', 'Environmental Technology and Industry Support Act, 2021', 'In March 2021, the Environmental Technology and Industry Support Act (ETISA) was amended to expand environmental disclosure obligations to all companies listed on the KOSPI Market Division of the Korea Exchange (KRX) (KOSPI Listed Companies) with total assets greater than or equal to KRW 2 trillion.', 'In March 2021, the Environmental Technology and Industry Support Act (ETISA) was amended to expand environmental disclosure obligations to all companies listed on the KOSPI Market Division of the Korea Exchange (KRX) (KOSPI Listed Companies) with total assets greater than or equal to KRW 2 trillion.', 'In March 2021, the Environmental Technology and Industry Support Act (ETISA) was amended to expand environmental disclosure obligations to all companies listed on the KOSPI Market Division of the Korea Exchange (KRX) (KOSPI Listed Companies) with total assets greater than or equal to KRW 2 trillion.', 'South Korea', 'climate', 'in_force', '2021-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_11', ARRAY['sdg14', 'regulations', 'sdg17', 'south korea', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8b11fa6-d908-5442-ba4c-8a4fee8c9498', 'South Korea K-ESG Guidelines v1.0', 'K-ESG Guidelines v1.0 2021', 'The K-ESG Guidelines v1.0 2021 from South Korea focus on promoting ESG (Environment, Social, Governance) management in companies. The guidelines emphasize the importance of sustainability in corporate activities and highlight the significance of ESG factors for sustainable growth. Companies in industries such as electronics, automobiles, ICT, chemicals, and textiles are required to create ESG performance and manage risks. The document discusses the global trend of ESG, the need for ESG internalization in corporate values, and the rise of ESG service markets.', 'The K-ESG Guidelines v1.0 2021 from South Korea focus on promoting ESG (Environment, Social, Governance) management in companies. The guidelines emphasize the importance of sustainability in corporate activities and highlight the significance of ESG factors for sustainable growth. Companies in industries such as electronics, automobiles, ICT, chemicals, and textiles are required to create ESG performance and manage risks. The document discusses the global trend of ESG, the need for ESG internalization in corporate values, and the rise of ESG service markets.', 'The K-ESG Guidelines v1.0 2021 from South Korea focus on promoting ESG (Environment, Social, Governance) management in companies. The guidelines emphasize the importance of sustainability in corporate activities and highlight the significance of ESG factors for sustainable growth. Companies in industries such as electronics, automobiles, ICT, chemicals, and textiles are required to create ESG performance and manage risks. The document discusses the global trend of ESG, the need for ESG internalization in corporate values, and the rise of ESG service markets.', 'South Korea', 'climate', 'in_force', '2021-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_12', ARRAY['guidance_frameworks', 'sdg7', 'south korea', 'sdg16', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2d742062-d497-5b30-91f1-b1c8b5b0be3a', 'South Korea Framework Act on Carbon Neutrality and Green', 'Framework Act on Carbon Neutrality and Green Growth for Climate Crisis Response (or “the Carbon Neutrality Act”)', 'This Act aims to mitigate climate change by reducing greenhouse gases, address resulting economic and social disparities, and promote green technology and industry, enhancing life quality and ecosystem protection for sustainable global development.', 'This Act aims to mitigate climate change by reducing greenhouse gases, address resulting economic and social disparities, and promote green technology and industry, enhancing life quality and ecosystem protection for sustainable global development.', 'This Act aims to mitigate climate change by reducing greenhouse gases, address resulting economic and social disparities, and promote green technology and industry, enhancing life quality and ecosystem protection for sustainable global development.', 'South Korea', 'climate', 'in_force', '2021-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_13', ARRAY['sdg13', 'regulations', 'sdg7', 'south korea', 'sdg9', 'mandatory', 'sdg12', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f6088335-b26b-5997-bc69-0fa461c38067', 'South Korea Business and Human Rights', 'Guidance on Business and Human Rights, 2021', 'These guidelines were drafted to help various members of business enterprises to understand the fundamental principles of business and human right, the human rights due diligence process, and remedial procedures.', 'These guidelines were drafted to help various members of business enterprises to understand the fundamental principles of business and human right, the human rights due diligence process, and remedial procedures.', 'These guidelines were drafted to help various members of business enterprises to understand the fundamental principles of business and human right, the human rights due diligence process, and remedial procedures.', 'South Korea', 'governance', 'in_force', '2021-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_17', ARRAY['guidance_frameworks', 'south korea', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9420d280-9c83-5c9f-a78e-7203b0aace8d', 'South Korea Disclosure of Corporate Governance', 'Guidelines on Disclosure of Corporate Governance, 2021', 'The 2021 South Korea Guidelines on Disclosure of Corporate Governance provide guidance to companies on how to disclose information related to their corporate governance practices. The guidelines apply to all listed companies in South Korea and aim to enhance transparency and accountability. The guidelines cover a wide range of topics, including the structure and composition of the board of directors, the independence and qualifications of directors, board committees, executive compensation, and shareholder rights. The guidelines emphasize the importance of disclosing information accurately and comprehensively to enable investors to make informed decisions. They also recommend that companies adopt international best practices and standards, such as those developed by the OECD and the International Corporate Governance Network. In addition to providing guidance on disclosure, the guidelines also recommend that companies establish appropriate corporate governance practices, such as a board of directors that is independent and competent, and effective risk management and internal control systems. The guidelines also encourage companies to engage with their shareholders and other stakeholders to promote long-term sustainable growth. The guidelines were developed by the Korea Exchange, the Financial Supervisory Service, and the Korea Corporate Governance Service, in collaboration with other stakeholders. They are expected to be reviewed periodically and updated as necessary to reflect changes in corporate governance practices and international standards.', 'The 2021 South Korea Guidelines on Disclosure of Corporate Governance provide guidance to companies on how to disclose information related to their corporate governance practices. The guidelines apply to all listed companies in South Korea and aim to enhance transparency and accountability. The guidelines cover a wide range of topics, including the structure and composition of the board of directors, the independence and qualifications of directors, board committees, executive compensation, and shareholder rights. The guidelines emphasize the importance of disclosing information accurately and comprehensively to enable investors to make informed decisions. They also recommend that companies adopt international best practices and standards, such as those developed by the OECD and the International Corporate Governance Network. In addition to providing guidance on disclosure, the guidelines also recommend that companies establish appropriate corporate governance practices, such as a board of directors that is independent and competent, and effective risk management and internal control systems. The guidelines also encourage companies to engage with their shareholders and other stakeholders to promote long-term sustainable growth. The guidelines were developed by the Korea Exchange, the Financial Supervisory Service, and the Korea Corporate Governance Service, in collaboration with other stakeholders. They are expected to be reviewed periodically and updated as necessary to reflect changes in corporate governance practices and international standards.', 'The 2021 South Korea Guidelines on Disclosure of Corporate Governance provide guidance to companies on how to disclose information related to their corporate governance practices. The guidelines apply to all listed companies in South Korea and aim to enhance transparency and accountability. The guidelines cover a wide range of topics, including the structure and composition of the board of directors, the independence and qualifications of directors, board committees, executive compensation, and shareholder rights. The guidelines emphasize the importance of disclosing information accurately and comprehensively to enable investors to make informed decisions. They also recommend that companies adopt international best practices and standards, such as those developed by the OECD and the International Corporate Governance Network. In addition to providing guidance on disclosure, the guidelines also recommend that companies establish appropriate corporate governance practices, such as a board of directors that is independent and competent, and effective risk management and internal control systems. The guidelines also encourage companies to engage with their shareholders and other stakeholders to promote long-term sustainable growth. The guidelines were developed by the Korea Exchange, the Financial Supervisory Service, and the Korea Corporate Governance Service, in collaboration with other stakeholders. They are expected to be reviewed periodically and updated as necessary to reflect changes in corporate governance practices and international standards.', 'South Korea', 'climate', 'in_force', '2021-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_8', ARRAY['guidance_frameworks', 'sdg17', 'south korea', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed8f7b36-49a1-533b-9e2b-cb8cb8ae90ca', 'South Korea Public Institution Human Rights Management Manual', 'Public Institution Human Rights Management Manual 2018', 'The ''Public Institution Human Rights Management Manual 2018'' from South Korea aims to guide public institutions in implementing human rights management systems. It outlines steps for establishing a human rights management framework, conducting human rights impact assessments, implementing human rights practices, and providing remedial procedures. The manual emphasizes the importance of preventing human rights violations by public institutions and aligning with national human rights policies. It offers a structured approach to enhance human rights protection, respect, and accountability within public organizations.', 'The ''Public Institution Human Rights Management Manual 2018'' from South Korea aims to guide public institutions in implementing human rights management systems. It outlines steps for establishing a human rights management framework, conducting human rights impact assessments, implementing human rights practices, and providing remedial procedures. The manual emphasizes the importance of preventing human rights violations by public institutions and aligning with national human rights policies. It offers a structured approach to enhance human rights protection, respect, and accountability within public organizations.', 'The ''Public Institution Human Rights Management Manual 2018'' from South Korea aims to guide public institutions in implementing human rights management systems. It outlines steps for establishing a human rights management framework, conducting human rights impact assessments, implementing human rights practices, and providing remedial procedures. The manual emphasizes the importance of preventing human rights violations by public institutions and aligning with national human rights policies. It offers a structured approach to enhance human rights protection, respect, and accountability within public organizations.', 'South Korea', 'climate', 'in_force', '2018-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_16', ARRAY['south korea', 'mandatory', 'sdg16', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e99fd751-f78b-508a-ba92-91c3145ce646', 'South Korea Guidelines on Disclosure of Corporate Governance', 'The Guidelines on Disclosure of Corporate Governance, 2018', 'The Guidelines on Disclosure of Corporate Governance, 2018 in South Korea mandate companies to disclose their compliance with corporate governance rules through reports. Firms must explain reasons for non-compliance and future plans, following the Key Principles of corporate governance. The report should detail items from the guideline and annexed table in a narrative style for investor understanding. The policy aims to enhance transparency and accountability in corporate governance practices.', 'The Guidelines on Disclosure of Corporate Governance, 2018 in South Korea mandate companies to disclose their compliance with corporate governance rules through reports. Firms must explain reasons for non-compliance and future plans, following the Key Principles of corporate governance. The report should detail items from the guideline and annexed table in a narrative style for investor understanding. The policy aims to enhance transparency and accountability in corporate governance practices.', 'The Guidelines on Disclosure of Corporate Governance, 2018 in South Korea mandate companies to disclose their compliance with corporate governance rules through reports. Firms must explain reasons for non-compliance and future plans, following the Key Principles of corporate governance. The report should detail items from the guideline and annexed table in a narrative style for investor understanding. The policy aims to enhance transparency and accountability in corporate governance practices.', 'South Korea', 'climate', 'in_force', '2018-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_7', ARRAY['guidance_frameworks', 'other sustainability policy', 'south korea', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('45e89fe7-b54b-5381-b964-be0c23ff61f4', 'South Korea Environmental Impact Assessment Act', 'Environmental Impact Assessment Act 2017', 'The purpose of this Act is to promote environment-friendly, sustainable development and healthy and pleasant life of citizens by forecasting and assessing the environmental impacts of a plan or project and by formulating measures for environmental conservation when a plan or project that has an environmental impact is formulated and implemented.', 'The purpose of this Act is to promote environment-friendly, sustainable development and healthy and pleasant life of citizens by forecasting and assessing the environmental impacts of a plan or project and by formulating measures for environmental conservation when a plan or project that has an environmental impact is formulated and implemented.', 'The purpose of this Act is to promote environment-friendly, sustainable development and healthy and pleasant life of citizens by forecasting and assessing the environmental impacts of a plan or project and by formulating measures for environmental conservation when a plan or project that has an environmental impact is formulated and implemented.', 'South Korea', 'climate', 'in_force', '2017-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_15', ARRAY['sdg2', 'regulations', 'sdg7', 'south korea', 'mandatory', 'sdg6', 'sdg12', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8edfb087-f940-598a-af02-2b1138cde7a7', 'South Korea Master Plan for Sustainable Development [2016-2035]', 'Master Plan for Sustainable Development [2016-2035]', 'The Master Plan for Sustainable Development [2016-2035] in South Korea aims to implement international agreements related to sustainable development and promote national sustainable development through a 20-year planning period. The plan focuses on establishing vision, goals, implementation strategies, principles, policy directions, and key indicators for sustainable development. It outlines concepts and achievements from UN reports and conferences, national action plans, sustainable development indicators, and key events. The plan emphasizes balancing economic growth, social integration, and environmental preservation for future generations.', 'The Master Plan for Sustainable Development [2016-2035] in South Korea aims to implement international agreements related to sustainable development and promote national sustainable development through a 20-year planning period. The plan focuses on establishing vision, goals, implementation strategies, principles, policy directions, and key indicators for sustainable development. It outlines concepts and achievements from UN reports and conferences, national action plans, sustainable development indicators, and key events. The plan emphasizes balancing economic growth, social integration, and environmental preservation for future generations.', 'The Master Plan for Sustainable Development [2016-2035] in South Korea aims to implement international agreements related to sustainable development and promote national sustainable development through a 20-year planning period. The plan focuses on establishing vision, goals, implementation strategies, principles, policy directions, and key indicators for sustainable development. It outlines concepts and achievements from UN reports and conferences, national action plans, sustainable development indicators, and key events. The plan emphasizes balancing economic growth, social integration, and environmental preservation for future generations.', 'South Korea', 'climate', 'in_force', '2016-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_1', ARRAY['sdg13', 'other sustainability policy', 'south korea', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59e947d6-fd5a-5cac-afda-aac9917afac7', 'South Korea Principles on the Stewardship Responsibilities of Institutional', 'Principles on the Stewardship Responsibilities of Institutional Investors', 'The Korea Stewardship Code, introduced in 2016, establishes principles to guide institutional investors in fulfilling their fiduciary responsibilities and promoting long-term value creation. The Code aligns with global stewardship practices and emphasizes transparency, accountability, and engagement with investee companies. It seeks to improve governance, ensure responsible investment practices, and enhance corporate sustainability in South Korea.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('495de6a7-dd2b-5ccf-a1d6-df48ccaf79af', 'South Korea Financial Investment Services and Capital Markets Act', 'The Financial Investment Services and Capital Markets Act', 'The purpose of this Act is to contribute to the development of the national economy by facilitating financial innovation and fair competition in the capital market, as well as protecting investors and fostering the development of the financial investment business, thereby heightening the fairness, reliability, and efficiency of the capital market.', 'The purpose of this Act is to contribute to the development of the national economy by facilitating financial innovation and fair competition in the capital market, as well as protecting investors and fostering the development of the financial investment business, thereby heightening the fairness, reliability, and efficiency of the capital market.', 'The purpose of this Act is to contribute to the development of the national economy by facilitating financial innovation and fair competition in the capital market, as well as protecting investors and fostering the development of the financial investment business, thereby heightening the fairness, reliability, and efficiency of the capital market.', 'South Korea', 'nature', 'in_force', '2013-01-01'::date, 'South Korea', 'https://www.carrotsandsticks.org/policies/93_2', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'south korea', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
