INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('679006bc-0e0d-5c01-a35b-f45fd202bd75', 'Spain Royal Decree , of March 18, which creates', 'Royal Decree 214/2025, of March 18, which creates the carbon footprint register, compensation and carbon dioxide absorption projects and establishes the obligation to calculate the carbon footprint and to prepare and publish greenhouse gas emission reduction plans.', 'Royal Decree 214/2025 in Spain establishes a carbon footprint register, requiring certain large companies and public entities to calculate their carbon footprint, publish reduction plans, and participate in carbon absorption projects. It aligns with climate change and energy transition laws, aiming to enhance transparency and reduce greenhouse gas emissions.', 'Royal Decree 214/2025 in Spain establishes a carbon footprint register, requiring certain large companies and public entities to calculate their carbon footprint, publish reduction plans, and participate in carbon absorption projects. It aligns with climate change and energy transition laws, aiming to enhance transparency and reduce greenhouse gas emissions.', 'Royal Decree 214/2025 in Spain establishes a carbon footprint register, requiring certain large companies and public entities to calculate their carbon footprint, publish reduction plans, and participate in carbon absorption projects. It aligns with climate change and energy transition laws, aiming to enhance transparency and reduce greenhouse gas emissions.', 'Spain', 'climate', 'in_force', '2025-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_64', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0d9a7c97-9685-5a0e-9b99-652adb336612', 'Spain Draft Law on Sustainable Consumption', 'Draft Law on Sustainable Consumption', 'The Draft Law on Sustainable Consumption in Spain aims to protect consumers and the environment by promoting conscious consumption, enhancing repair options, and ensuring clear environmental information. It aligns with EU directives to advance sustainable practices, empower consumers, and discourage early product obsolescence, fostering a shift towards a circular economy.', 'The Draft Law on Sustainable Consumption in Spain aims to protect consumers and the environment by promoting conscious consumption, enhancing repair options, and ensuring clear environmental information. It aligns with EU directives to advance sustainable practices, empower consumers, and discourage early product obsolescence, fostering a shift towards a circular economy.', 'The Draft Law on Sustainable Consumption in Spain aims to protect consumers and the environment by promoting conscious consumption, enhancing repair options, and ensuring clear environmental information. It aligns with EU directives to advance sustainable practices, empower consumers, and discourage early product obsolescence, fostering a shift towards a circular economy.', 'Spain', 'circularity', 'in_force', '2025-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_65', ARRAY['spain', 'mandatory', 'sdg12', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed2e0287-91df-5222-9255-2754ec52162c', 'Spain Law , of December 3, on Sustainable Mobility', 'Law 9/2025, of December 3, on Sustainable Mobility.', 'Law 9/2025 in Spain focuses on Sustainable Mobility, aiming to improve transportation systems and promote eco-friendly practices. It outlines guidelines for sustainable mobility planning, infrastructure management, state funding, innovation in transportation, and public participation. This policy targets all citizens and stakeholders involved in the transportation sector.', 'Law 9/2025 in Spain focuses on Sustainable Mobility, aiming to improve transportation systems and promote eco-friendly practices. It outlines guidelines for sustainable mobility planning, infrastructure management, state funding, innovation in transportation, and public participation. This policy targets all citizens and stakeholders involved in the transportation sector.', 'Law 9/2025 in Spain focuses on Sustainable Mobility, aiming to improve transportation systems and promote eco-friendly practices. It outlines guidelines for sustainable mobility planning, infrastructure management, state funding, innovation in transportation, and public participation. This policy targets all citizens and stakeholders involved in the transportation sector.', 'Spain', 'climate', 'in_force', '2025-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_66', ARRAY['regulations', 'sdg11', 'mandatory', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('788b5266-6f27-558b-a1b6-88b490584794', 'Spain Law , of April 1, on the prevention', 'Law 1/2025, of April 1, on the prevention of food loss and waste.', 'Law 1/2025 in Spain aims to prevent food loss and waste. It outlines obligations for all actors in the food supply chain, including specific requirements for hospitality businesses and social organizations. The policy promotes good practices, rationalizes consumption dates, and includes a sanctions regime for non-compliance.', 'Law 1/2025 in Spain aims to prevent food loss and waste. It outlines obligations for all actors in the food supply chain, including specific requirements for hospitality businesses and social organizations. The policy promotes good practices, rationalizes consumption dates, and includes a sanctions regime for non-compliance.', 'Law 1/2025 in Spain aims to prevent food loss and waste. It outlines obligations for all actors in the food supply chain, including specific requirements for hospitality businesses and social organizations. The policy promotes good practices, rationalizes consumption dates, and includes a sanctions regime for non-compliance.', 'Spain', 'nature', 'in_force', '2025-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_67', ARRAY['spain', 'mandatory', 'sdg12', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1dac94d5-d462-59dd-b877-ae9d4c71b154', 'Spain related products, and amending other tax regulations', 'Law 7/2024, of December 20, establishing a Complementary Tax to guarantee a global minimum level of taxation for multinational groups and large national groups, a Tax on the margin of interest and commissions of certain financial entities and a Tax on liquids for electronic cigarettes and other tobacco-related products, and amending other tax regulations.', 'Law 7/2024 in Spain introduces a Complementary Tax to ensure a global minimum level of taxation for multinational and large national groups, as well as taxes on financial entities'' interests, commissions, and e-cigarette products. It outlines taxable subjects, rules, and adjustments for taxable income. Targeted at entities subject to the specified taxes.', 'Law 7/2024 in Spain introduces a Complementary Tax to ensure a global minimum level of taxation for multinational and large national groups, as well as taxes on financial entities'' interests, commissions, and e-cigarette products. It outlines taxable subjects, rules, and adjustments for taxable income. Targeted at entities subject to the specified taxes.', 'Law 7/2024 in Spain introduces a Complementary Tax to ensure a global minimum level of taxation for multinational and large national groups, as well as taxes on financial entities'' interests, commissions, and e-cigarette products. It outlines taxable subjects, rules, and adjustments for taxable income. Targeted at entities subject to the specified taxes.', 'Spain', 'governance', 'in_force', '2024-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_68', ARRAY['spain', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f98d030-e0cf-54f0-82c7-b40963166ae6', 'Spain Law on Business Information on Sustainability (LEIS)', 'The Law on Business Information on Sustainability (LEIS)', 'The Law on Business Information on Sustainability (LEIS) aims to enhance the framework for sustainability reporting in Spain, aligning with EU Directive 2022/2464. It mandates large companies and certain SMEs to disclose sustainability information, including environmental, social, and governance factors. The law modifies existing commercial and auditing codes and introduces verification requirements for the disclosed information. It applies to all large companies and SMEs with publicly traded securities, while microenterprises are exempt. The law is mandatory and effective from January 1, 2024.', 'The Law on Business Information on Sustainability (LEIS) aims to enhance the framework for sustainability reporting in Spain, aligning with EU Directive 2022/2464. It mandates large companies and certain SMEs to disclose sustainability information, including environmental, social, and governance factors. The law modifies existing commercial and auditing codes and introduces verification requirements for the disclosed information. It applies to all large companies and SMEs with publicly traded securities, while microenterprises are exempt. The law is mandatory and effective from January 1, 2024.', 'The Law on Business Information on Sustainability (LEIS) aims to enhance the framework for sustainability reporting in Spain, aligning with EU Directive 2022/2464. It mandates large companies and certain SMEs to disclose sustainability information, including environmental, social, and governance factors. The law modifies existing commercial and auditing codes and introduces verification requirements for the disclosed information. It applies to all large companies and SMEs with publicly traded securities, while microenterprises are exempt. The law is mandatory and effective from January 1, 2024.', 'Spain', 'climate', 'in_force', '2024-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_69', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e1e4d903-0b90-53fc-b18b-77875d7cda93', 'Spain BME Voluntary Guidance on Sustainability Information for Listed', 'BME Voluntary Guidance on Sustainability Information for Listed Companies', 'BME´s Voluntary Sustainability Reporting Guidelines for Listed Companies is intended as a base model or guide for voluntary use by those companies listed on their markets that wish to inform the financial commu­nity about environmental, sustainability and corporate governance aspects of their activity. The guide contains a set of ten recommendations and five steps to be fol­lowed, which are in no way binding companies wishing to have a guide for reporting on these aspects.', 'BME´s Voluntary Sustainability Reporting Guidelines for Listed Companies is intended as a base model or guide for voluntary use by those companies listed on their markets that wish to inform the financial commu­nity about environmental, sustainability and corporate governance aspects of their activity. The guide contains a set of ten recommendations and five steps to be fol­lowed, which are in no way binding companies wishing to have a guide for reporting on these aspects.', 'BME´s Voluntary Sustainability Reporting Guidelines for Listed Companies is intended as a base model or guide for voluntary use by those companies listed on their markets that wish to inform the financial commu­nity about environmental, sustainability and corporate governance aspects of their activity. The guide contains a set of ten recommendations and five steps to be fol­lowed, which are in no way binding companies wishing to have a guide for reporting on these aspects.', 'Spain', 'climate', 'in_force', '2023-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_63', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'spain', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('16415050-dfb0-566e-bead-4f763e011930', 'Spain Code of Ethics for Companies Digital Edition', 'Code of Ethics for Companies Digital Edition', 'Even though this Code is created with the intention of being generally applicable to all companies, it must also be understood as a general and basic framework that can be adapted to the peculiarities of each one, in such a way that it contemplates the application of principles of ethics and sustainable development in line with the specific activity of the company.', 'Even though this Code is created with the intention of being generally applicable to all companies, it must also be understood as a general and basic framework that can be adapted to the peculiarities of each one, in such a way that it contemplates the application of principles of ethics and sustainable development in line with the specific activity of the company.', 'Even though this Code is created with the intention of being generally applicable to all companies, it must also be understood as a general and basic framework that can be adapted to the peculiarities of each one, in such a way that it contemplates the application of principles of ethics and sustainable development in line with the specific activity of the company.', 'Spain', 'climate', 'in_force', '2022-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_50', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('193c5220-ef22-533c-959f-085a9670e5a6', 'Spain Annual Regulatory Plan 2022 General State Administration', 'Annual Regulatory Plan 2022 General State Administration', 'The Plan Anual Normativo 2022 of the General State Administration of Spain is a document that presents the annual plan of normative activity of the different government departments for the year 2022. The plan includes a list of the normative projects that will be developed, modified, or repealed in the upcoming year. The document is organized by different areas of action, including economic affairs, justice, environment, and social issues, among others. Each area includes a list of normative projects, with a brief description of the objectives and expected outcomes. The Plan outlines various regulatory measures that will affect businesses and companies operating within the country. These measures include changes to taxation and labor regulations, as well as updates to consumer protection laws and environmental standards. The plan also emphasizes the importance of promoting digitalization and innovation in business practices. Companies should take note of these regulatory developments and ensure that they are in compliance with the new requirements in order to avoid potential legal and financial penalties.', 'The Plan Anual Normativo 2022 of the General State Administration of Spain is a document that presents the annual plan of normative activity of the different government departments for the year 2022. The plan includes a list of the normative projects that will be developed, modified, or repealed in the upcoming year. The document is organized by different areas of action, including economic affairs, justice, environment, and social issues, among others. Each area includes a list of normative projects, with a brief description of the objectives and expected outcomes. The Plan outlines various regulatory measures that will affect businesses and companies operating within the country. These measures include changes to taxation and labor regulations, as well as updates to consumer protection laws and environmental standards. The plan also emphasizes the importance of promoting digitalization and innovation in business practices. Companies should take note of these regulatory developments and ensure that they are in compliance with the new requirements in order to avoid potential legal and financial penalties.', 'The Plan Anual Normativo 2022 of the General State Administration of Spain is a document that presents the annual plan of normative activity of the different government departments for the year 2022. The plan includes a list of the normative projects that will be developed, modified, or repealed in the upcoming year. The document is organized by different areas of action, including economic affairs, justice, environment, and social issues, among others. Each area includes a list of normative projects, with a brief description of the objectives and expected outcomes. The Plan outlines various regulatory measures that will affect businesses and companies operating within the country. These measures include changes to taxation and labor regulations, as well as updates to consumer protection laws and environmental standards. The plan also emphasizes the importance of promoting digitalization and innovation in business practices. Companies should take note of these regulatory developments and ensure that they are in compliance with the new requirements in order to avoid potential legal and financial penalties.', 'Spain', 'climate', 'in_force', '2022-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_62', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a68a389-6f21-5dba-b9f0-e77de4ccf090', 'Spain Law , of May 20, on climate change', 'Law 7/2021, of May 20, on climate change and energy transition', 'This document is concerned with Law 7/2021, of May 20, on climate change and energy transition.', 'This document is concerned with Law 7/2021, of May 20, on climate change and energy transition.', 'This document is concerned with Law 7/2021, of May 20, on climate change and energy transition.', 'Spain', 'climate', 'in_force', '2021-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_49', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c6992882-c8e0-5926-ba16-aaf933076484', 'Spain Circular Economy Spanish Strategy', 'Circular Economy Spanish Strategy', 'The Ministry for the Ecological Transition and the Demographic Challenge of Spain has published a Circular Economy Strategy that sets an important benchmark in this area at the national level. This strategy establishes a series of objectives for the next decade, setting out the main lines of action on which all policies and instruments will focus, such as production, consumption, waste management, secondary raw materials and water reuse.  In a transversal way, the following axes have also been incorporated into this Strategy: Awareness and participation; research, innovation and competitiveness; and employment and training.', 'The Ministry for the Ecological Transition and the Demographic Challenge of Spain has published a Circular Economy Strategy that sets an important benchmark in this area at the national level. This strategy establishes a series of objectives for the next decade, setting out the main lines of action on which all policies and instruments will focus, such as production, consumption, waste management, secondary raw materials and water reuse.  In a transversal way, the following axes have also been incorporated into this Strategy: Awareness and participation; research, innovation and competitiveness; and employment and training.', 'The Ministry for the Ecological Transition and the Demographic Challenge of Spain has published a Circular Economy Strategy that sets an important benchmark in this area at the national level. This strategy establishes a series of objectives for the next decade, setting out the main lines of action on which all policies and instruments will focus, such as production, consumption, waste management, secondary raw materials and water reuse.  In a transversal way, the following axes have also been incorporated into this Strategy: Awareness and participation; research, innovation and competitiveness; and employment and training.', 'Spain', 'climate', 'in_force', '2021-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_51', ARRAY['sdg4', 'sdg8', 'sdg14', 'other sustainability policy', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('528515cb-26bd-5be5-a415-16e49f2b01f6', 'Spain Law , of May 20, on climate change', 'Law 7/2021, of May 20, on climate change and energy transition', 'This law sets out a comprehensive framework for Spain''s transition to a more sustainable, low-carbon economy. It establishes targets for reducing greenhouse gas emissions and increasing the share of renewable energy in the country''s energy mix. The law also includes measures to promote energy efficiency, sustainable mobility, and circular economy practices. It establishes a framework for financing the transition to a low-carbon economy and provides for the creation of a new regulatory authority to oversee the implementation of the law. The aim of the law is to ensure that Spain contributes to the global effort to combat climate change and to promote sustainable development in the country.', 'This law sets out a comprehensive framework for Spain''s transition to a more sustainable, low-carbon economy. It establishes targets for reducing greenhouse gas emissions and increasing the share of renewable energy in the country''s energy mix. The law also includes measures to promote energy efficiency, sustainable mobility, and circular economy practices. It establishes a framework for financing the transition to a low-carbon economy and provides for the creation of a new regulatory authority to oversee the implementation of the law. The aim of the law is to ensure that Spain contributes to the global effort to combat climate change and to promote sustainable development in the country.', 'This law sets out a comprehensive framework for Spain''s transition to a more sustainable, low-carbon economy. It establishes targets for reducing greenhouse gas emissions and increasing the share of renewable energy in the country''s energy mix. The law also includes measures to promote energy efficiency, sustainable mobility, and circular economy practices. It establishes a framework for financing the transition to a low-carbon economy and provides for the creation of a new regulatory authority to oversee the implementation of the law. The aim of the law is to ensure that Spain contributes to the global effort to combat climate change and to promote sustainable development in the country.', 'Spain', 'climate', 'in_force', '2020-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_30', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('20b6c4cd-6dc9-593c-bab4-9836395d964b', 'Spain Good Governance Code of Listed Companies Revised June', 'Good Governance Code of Listed Companies Revised June 2020', 'Four years after the approval of the Good Governance Code, the CNMV’s Activity Plan for 2019 included the objective of reviewing and clarifying some of its recom­ mendations. Once the corresponding texts had been prepared, it was resolved to expand the scope of the reform to add the review of some additional aspects, which was included in the Activity Plan for 2020. The proposed amendment, which is lim­ ited in scope, was submitted to public consultation between 15 January and 14 Feb­ ruary 2020, and a number of opinions and comments were submitted by various corporations and stakeholders that were taken into account to determine the final scope of the changes made.', 'Four years after the approval of the Good Governance Code, the CNMV’s Activity Plan for 2019 included the objective of reviewing and clarifying some of its recom­ mendations. Once the corresponding texts had been prepared, it was resolved to expand the scope of the reform to add the review of some additional aspects, which was included in the Activity Plan for 2020. The proposed amendment, which is lim­ ited in scope, was submitted to public consultation between 15 January and 14 Feb­ ruary 2020, and a number of opinions and comments were submitted by various corporations and stakeholders that were taken into account to determine the final scope of the changes made.', 'Four years after the approval of the Good Governance Code, the CNMV’s Activity Plan for 2019 included the objective of reviewing and clarifying some of its recom­ mendations. Once the corresponding texts had been prepared, it was resolved to expand the scope of the reform to add the review of some additional aspects, which was included in the Activity Plan for 2020. The proposed amendment, which is lim­ ited in scope, was submitted to public consultation between 15 January and 14 Feb­ ruary 2020, and a number of opinions and comments were submitted by various corporations and stakeholders that were taken into account to determine the final scope of the changes made.', 'Spain', 'governance', 'in_force', '2020-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_43', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('649dd2ca-839b-5ee9-a688-e8df1e7c3905', 'Spain Royal Decree , of October 13, on equal', 'Royal Decree 902/2020, of October 13, on equal pay between women and men', 'This is the Royal Decree 902/2020, of October 13, on equal pay between women and men.', 'This is the Royal Decree 902/2020, of October 13, on equal pay between women and men.', 'This is the Royal Decree 902/2020, of October 13, on equal pay between women and men.', 'Spain', 'social', 'in_force', '2020-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_44', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg5', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2dc163e6-3bf7-552c-9c16-aaf4972699d2', 'Spain Royal Decree , of October 13, which regulates', 'Royal Decree 901/2020, of October 13, which regulates equality plans and their registration and modifies Royal Decree 713/2010, of May 28, on the registration and deposit of agreements and collective labor agreements', 'Royal Decree-Law 6/2019, of March 1, on urgent measures to guarantee equal treatment and opportunities between women and men in employment and occupation, incorporated very significant changes in Organic Law 3/2007, of March 22, for the effective equality of women and men, in terms of equality plans: in the first place, it altered its article 45.2, establishing the obligation that all companies with fifty or more workers prepare and apply an equality plan equality. In this way, the number of companies required to have an equality plan was considerably increased, given that previously only companies with more than two hundred and fifty workers had this obligation. In order for the expansion of the companies required to carry out the equality plan to be carried out gradually, a twelfth transitory provision was incorporated into Organic Law 3/2007, of March 22.', 'Royal Decree-Law 6/2019, of March 1, on urgent measures to guarantee equal treatment and opportunities between women and men in employment and occupation, incorporated very significant changes in Organic Law 3/2007, of March 22, for the effective equality of women and men, in terms of equality plans: in the first place, it altered its article 45.2, establishing the obligation that all companies with fifty or more workers prepare and apply an equality plan equality. In this way, the number of companies required to have an equality plan was considerably increased, given that previously only companies with more than two hundred and fifty workers had this obligation. In order for the expansion of the companies required to carry out the equality plan to be carried out gradually, a twelfth transitory provision was incorporated into Organic Law 3/2007, of March 22.', 'Royal Decree-Law 6/2019, of March 1, on urgent measures to guarantee equal treatment and opportunities between women and men in employment and occupation, incorporated very significant changes in Organic Law 3/2007, of March 22, for the effective equality of women and men, in terms of equality plans: in the first place, it altered its article 45.2, establishing the obligation that all companies with fifty or more workers prepare and apply an equality plan equality. In this way, the number of companies required to have an equality plan was considerably increased, given that previously only companies with more than two hundred and fifty workers had this obligation. In order for the expansion of the companies required to carry out the equality plan to be carried out gradually, a twelfth transitory provision was incorporated into Organic Law 3/2007, of March 22.', 'Spain', 'climate', 'in_force', '2020-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_45', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg5', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('74477955-830e-5cd7-a1c5-b333c9806404', 'Spain Royal Decree-Law , of September 22, on remote', 'Royal Decree-Law 28/2020, of September 22, on remote work', 'This document is concerned with the topic of remote work, understood as work that is carried out outside the company''s usual establishments and centers and of which telework is a subspecies that involves the provision of services with new technologies. It outlines how it has been subject to regulation both internally and at the community and international level.', 'This document is concerned with the topic of remote work, understood as work that is carried out outside the company''s usual establishments and centers and of which telework is a subspecies that involves the provision of services with new technologies. It outlines how it has been subject to regulation both internally and at the community and international level.', 'This document is concerned with the topic of remote work, understood as work that is carried out outside the company''s usual establishments and centers and of which telework is a subspecies that involves the provision of services with new technologies. It outlines how it has been subject to regulation both internally and at the community and international level.', 'Spain', 'nature', 'in_force', '2020-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_46', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'spain', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
