INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08608b77-c3e7-595e-89b6-907fabe35062', 'Spain Law , of December 16, which modifies Law', 'Law 9/2020, of December 16, which modifies Law 1/2005, of March 9, which regulates the trading regime of greenhouse gas emission rights, to intensify the reductions of emissions cost-effectively', 'Directive 2003/87/CE, of the European Parliament and of the Council, of October 13, 2003, establishes a system for the trading of greenhouse gas emission rights in the Community and which modifies Council Directive 96/61/EC established the European Union emission rights trading system in order to encourage the reduction of emissions of these gases in an effective, cost-effective and economically efficient manner. This directive was transposed into the Spanish legal system through Law 1/2005, of March 9, which regulates the greenhouse gas emission rights trading system.', 'Directive 2003/87/CE, of the European Parliament and of the Council, of October 13, 2003, establishes a system for the trading of greenhouse gas emission rights in the Community and which modifies Council Directive 96/61/EC established the European Union emission rights trading system in order to encourage the reduction of emissions of these gases in an effective, cost-effective and economically efficient manner. This directive was transposed into the Spanish legal system through Law 1/2005, of March 9, which regulates the greenhouse gas emission rights trading system.', 'Directive 2003/87/CE, of the European Parliament and of the Council, of October 13, 2003, establishes a system for the trading of greenhouse gas emission rights in the Community and which modifies Council Directive 96/61/EC established the European Union emission rights trading system in order to encourage the reduction of emissions of these gases in an effective, cost-effective and economically efficient manner. This directive was transposed into the Spanish legal system through Law 1/2005, of March 9, which regulates the greenhouse gas emission rights trading system.', 'Spain', 'climate', 'in_force', '2020-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_48', ARRAY['sdg13', 'regulations', 'sdg11', 'mandatory', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ad36f73-52a0-5235-8afa-a7c7f8877beb', 'Spain Royal Decree-Law , of March 1, on urgent', 'Royal Decree-Law 6/2019, of March 1, on urgent measures to guarantee equal treatment and opportunities between women and men in employment and occupation', 'The Organic Law 3/2007, of March 22, for the effective equality of women and men, aimed to make effective the principle of equal treatment and opportunities between women and men, in particular by eliminating all discrimination, direct and indirectly, of women. It was a pioneering law in the legislative development of gender equality rights in Spain.', 'The Organic Law 3/2007, of March 22, for the effective equality of women and men, aimed to make effective the principle of equal treatment and opportunities between women and men, in particular by eliminating all discrimination, direct and indirectly, of women. It was a pioneering law in the legislative development of gender equality rights in Spain.', 'The Organic Law 3/2007, of March 22, for the effective equality of women and men, aimed to make effective the principle of equal treatment and opportunities between women and men, in particular by eliminating all discrimination, direct and indirectly, of women. It was a pioneering law in the legislative development of gender equality rights in Spain.', 'Spain', 'climate', 'in_force', '2019-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_40', ARRAY['sdg8', 'other sustainability policy', 'sdg10', 'regulations', 'mandatory', 'sdg5', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
