INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9d5aaf52-0f6f-59ad-8061-4ad9cb558192', 'Spain Resolution of March 5, 2019, of the Institute', 'Resolution of March 5, 2019, of the Institute of Accounting and Auditing of Accounts, which develops the criteria for the presentation of financial instruments and other accounting aspects related to the commercial regulation of capital companies', 'The General Accounting Plan (PGC) approved by Royal Decree 1514/2007, of November 16, includes in its Second Part the registration and valuation rules that develop the accounting principles and other provisions contained in the First Part related to the Conceptual Framework of Accounting.', 'The General Accounting Plan (PGC) approved by Royal Decree 1514/2007, of November 16, includes in its Second Part the registration and valuation rules that develop the accounting principles and other provisions contained in the First Part related to the Conceptual Framework of Accounting.', 'The General Accounting Plan (PGC) approved by Royal Decree 1514/2007, of November 16, includes in its Second Part the registration and valuation rules that develop the accounting principles and other provisions contained in the First Part related to the Conceptual Framework of Accounting.', 'Spain', 'governance', 'in_force', '2019-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_42', ARRAY['spain', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
