INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a9b390c4-f42e-572e-9827-bf957be90e9b', 'Spain Practical guide to good governance for NGOs: Public', 'Practical guide to good governance for NGOs: Public Utility Associations and Foundations', 'This is the first edition of the “Practical Guide to Good Governance for NGOs: Public Utility Associations and Foundations”, has been prepared by the Institute of Directors-Administrators (IC-A), the Spanish Association of Directors, in close coordination with the Third Sector you have had a Working Group created “ex profeso” for this purpose.', 'This is the first edition of the “Practical Guide to Good Governance for NGOs: Public Utility Associations and Foundations”, has been prepared by the Institute of Directors-Administrators (IC-A), the Spanish Association of Directors, in close coordination with the Third Sector you have had a Working Group created “ex profeso” for this purpose.', 'This is the first edition of the “Practical Guide to Good Governance for NGOs: Public Utility Associations and Foundations”, has been prepared by the Institute of Directors-Administrators (IC-A), the Spanish Association of Directors, in close coordination with the Third Sector you have had a Working Group created “ex profeso” for this purpose.', 'Spain', 'climate', 'in_force', '2018-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_39', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e3abcca5-2b79-5294-a62f-eec6e25c0326', 'Spain National Action Plan on Business and Human Rights', 'National Action Plan on Business and Human Rights', 'This document presents Spain’s National Action Plan to implement the UN Guiding Principles on Business and Human Rights. Through this Plan—as a specific manifestation of our broader commitment to protecting and promoting human rights—Spain undertakes to protect human rights against any adverse impacts from business activities, and to provide the potential victims of such impacts with an effective remedy.', 'This document presents Spain’s National Action Plan to implement the UN Guiding Principles on Business and Human Rights. Through this Plan—as a specific manifestation of our broader commitment to protecting and promoting human rights—Spain undertakes to protect human rights against any adverse impacts from business activities, and to provide the potential victims of such impacts with an effective remedy.', 'This document presents Spain’s National Action Plan to implement the UN Guiding Principles on Business and Human Rights. Through this Plan—as a specific manifestation of our broader commitment to protecting and promoting human rights—Spain undertakes to protect human rights against any adverse impacts from business activities, and to provide the potential victims of such impacts with an effective remedy.', 'Spain', 'governance', 'in_force', '2017-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_31', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d5f0caf6-3b4e-52fe-ad59-e735c42889f6', 'Spain Royal Decree , of June 23, which approves', 'Royal Decree 656/2017, of June 23, which approves the Chemical Products Storage Regulation and its Complementary Technical Instructions MIE APQ 0 to 10', 'Law 21/1992, of July 16, on Industry, establishes in its article 12.5, that the Industrial Safety Regulations at state level will be approved by the National Government, without prejudice to the fact that the Autonomous Communities with legislative powers on industry, may introduce additional requirements on the same matters in the case of facilities located in their territory.', 'Law 21/1992, of July 16, on Industry, establishes in its article 12.5, that the Industrial Safety Regulations at state level will be approved by the National Government, without prejudice to the fact that the Autonomous Communities with legislative powers on industry, may introduce additional requirements on the same matters in the case of facilities located in their territory.', 'Law 21/1992, of July 16, on Industry, establishes in its article 12.5, that the Industrial Safety Regulations at state level will be approved by the National Government, without prejudice to the fact that the Autonomous Communities with legislative powers on industry, may introduce additional requirements on the same matters in the case of facilities located in their territory.', 'Spain', 'governance', 'in_force', '2017-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_38', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'spain', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
