INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1da53668-50bb-53d1-acd4-149f28bf91d1', 'Spain Code of good governance of listed companies', 'Code of good governance of listed companies', 'The unified code of good governance of listed companies (hereinafter Unified Code) was approved by Agreement of the Council of the National Securities Market Commission (CNMV) of May 22, 2006, as a single document, together with the recommendations of governance for the purposes of the provisions of the first provision of section 1. f) of Order ECO/3722/2003, of December 26.', 'The unified code of good governance of listed companies (hereinafter Unified Code) was approved by Agreement of the Council of the National Securities Market Commission (CNMV) of May 22, 2006, as a single document, together with the recommendations of governance for the purposes of the provisions of the first provision of section 1. f) of Order ECO/3722/2003, of December 26.', 'The unified code of good governance of listed companies (hereinafter Unified Code) was approved by Agreement of the Council of the National Securities Market Commission (CNMV) of May 22, 2006, as a single document, together with the recommendations of governance for the purposes of the provisions of the first provision of section 1. f) of Order ECO/3722/2003, of December 26.', 'Spain', 'governance', 'in_force', '2015-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_13', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'spain']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('087f1458-15e2-57dc-b79b-a2571d4b7b07', 'Spain Practical Guide of the Board of Directors', 'Practical Guide of the Board of Directors', 'This Guide analyses and describes, mainly from practical standpoint, the duties and liability of directors of a Spanish capital stock company. It intends to clearly explain how directors should behave to fulfil their duties and provides guidelines on how they should perform their functions.', 'This Guide analyses and describes, mainly from practical standpoint, the duties and liability of directors of a Spanish capital stock company. It intends to clearly explain how directors should behave to fulfil their duties and provides guidelines on how they should perform their functions.', 'This Guide analyses and describes, mainly from practical standpoint, the duties and liability of directors of a Spanish capital stock company. It intends to clearly explain how directors should behave to fulfil their duties and provides guidelines on how they should perform their functions.', 'Spain', 'governance', 'in_force', '2015-01-01'::date, 'Spain', 'https://www.carrotsandsticks.org/policies/168_17', ARRAY['spain', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
